22	func extErrBytes(errno uint32, origin, icmpType, icmpCode uint8, family uint16, port uint16, sender [4]byte) []byte {
23		b := make([]byte, 32)
24		binary.NativeEndian.PutUint32(b[0:4], errno)
25		b[4] = origin
